"""Input and output format helpers for the Dasel-compatible CLI."""
import csv
import io
import json
try:
    import tomllib
except ImportError:
    tomllib = None


def detect_format(name):
    n=(name or '').lower().lstrip('.')
    aliases={'yml':'yaml','htm':'html'}
    return aliases.get(n,n or 'json')


def load_data(text, fmt='json', flags=None):
    fmt=detect_format(fmt)
    if fmt in ('json','jsonl'):
        if fmt=='jsonl': return [json.loads(line) for line in text.splitlines() if line.strip()]
        return json.loads(text)
    if fmt=='toml': return tomllib.loads(text) if tomllib else parse_toml(text)
    if fmt=='csv':
        rows=list(csv.DictReader(io.StringIO(text), delimiter=(flags or {}).get('csv-delimiter', ',')))
        # CSV reader values are strings; preserve empty cells as empty strings.
        return rows
    if fmt in ('yaml','yml'):
        return parse_yaml(text)
    raise ValueError(f"unsupported input format: {fmt}")


def parse_toml(text):
    root={}; current=root
    def val(s):
        s=s.strip()
        if s.startswith(('\"', "'")):
            try: return json.loads(s) if s.startswith('\"') else s[1:-1]
            except Exception: return s[1:-1]
        if s.lower() in ('true','false'): return s.lower()=='true'
        if s.startswith('[') and s.endswith(']'):
            return [val(x) for x in s[1:-1].split(',') if x.strip()]
        try: return int(s.replace('_',''))
        except Exception: pass
        try: return float(s.replace('_',''))
        except Exception: return s
    for line in text.splitlines():
        line=line.split('#',1)[0].strip()
        if not line: continue
        if line.startswith('[') and line.endswith(']'):
            current=root
            for part in line[1:-1].split('.'):
                current=current.setdefault(part.strip(),{})
            continue
        if '=' in line:
            key,value=line.split('=',1); current[key.strip()]=val(value)
    return root


def parse_yaml(text):
    # Small indentation-based YAML subset, intentionally dependency-free.
    lines=[]
    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith('#'): continue
        indent=len(raw)-len(raw.lstrip(' ')); lines.append((indent,raw.strip()))
    if not lines: return None
    def scalar(s):
        s=s.strip()
        if s in ('null','~'): return None
        if s.lower() in ('true','false'): return s.lower()=='true'
        if s.startswith(('"',"'",'[','{')):
            try: return json.loads(s.replace("'",'"') if s.startswith("'") else s)
            except Exception: pass
        try: return int(s)
        except Exception: pass
        try: return float(s)
        except Exception: return s
    def block(i, indent):
        arr=lines[i][1].startswith('- ' ) or lines[i][1]=='-'
        out=[] if arr else {}
        while i<len(lines) and lines[i][0]==indent:
            t=lines[i][1]
            if arr:
                if not t.startswith('-'): break
                v=t[1:].strip(); i+=1
                if i<len(lines) and lines[i][0]>indent: val,i=block(i,lines[i][0])
                else: val=scalar(v) if v else None
                out.append(val)
            else:
                if ':' not in t: i+=1; continue
                k,v=t.split(':',1); k=str(scalar(k)); v=v.strip(); i+=1
                if i<len(lines) and lines[i][0]>indent: val,i=block(i,lines[i][0])
                else: val=scalar(v) if v else None
                out[k]=val
        return out,i
    return block(0,lines[0][0])[0]


def dump_data(value, fmt='json', compact=False, flags=None):
    fmt=detect_format(fmt)
    if fmt=='json':
        return json.dumps(value,ensure_ascii=False,separators=(',',':') if compact else (', ', ': '),indent=None if compact else 4)
    if fmt=='yaml': return dump_yaml(value)
    if fmt=='toml': return dump_toml(value)
    if fmt=='csv':
        if not isinstance(value,list): raise ValueError(f'csv writer expects root output to be a slice/array, got {kind(value)}')
        if not value: return ''
        if not all(isinstance(row,dict) for row in value): raise ValueError('csv writer expects array of maps')
        fields=[]
        for row in value:
            for k in row:
                if k not in fields: fields.append(k)
        s=io.StringIO(newline=''); w=csv.DictWriter(s,fieldnames=fields,delimiter=(flags or {}).get('csv-delimiter',','),lineterminator='\n'); w.writeheader(); w.writerows(value)
        return s.getvalue().rstrip('\n')
    raise ValueError(f'unsupported output format: {fmt}')


def kind(v):
    return {dict:'map',list:'slice',str:'string',bool:'bool',int:'int',float:'float',type(None):'nil'}.get(type(v),'value')


def dump_yaml(v, level=0):
    pad='  '*level
    def scalar(x):
        if isinstance(x,str):
            if not x or any(c in x for c in ':#{}[],&*!|>\n') or x.strip()!=x or x.lower() in ('true','false','null','~'):
                return json.dumps(x,ensure_ascii=False)
            return x
        if x is None:return 'null'
        if isinstance(x,bool):return str(x).lower()
        return str(x)
    if isinstance(v,dict):
        out=[]
        for k,x in v.items():
            if isinstance(x,(dict,list)) and x: out.append(pad+scalar(str(k))+':\n'+dump_yaml(x,level+1))
            else: out.append(pad+scalar(str(k))+': '+(scalar(x) if not isinstance(x,(dict,list)) else ('{}' if isinstance(x,dict) else '[]')))
        return '\n'.join(out)
    if isinstance(v,list):
        out=[]
        for x in v:
            if isinstance(x,(dict,list)) and x: out.append(pad+'-\n'+dump_yaml(x,level+1))
            else: out.append(pad+'- '+(scalar(x) if not isinstance(x,(dict,list)) else ('{}' if isinstance(x,dict) else '[]')))
        return '\n'.join(out)
    return pad+scalar(v)


def dump_toml(v):
    if not isinstance(v,dict): raise ValueError('toml writer expects root output to be a map')
    lines=[]
    def val(x):
        if isinstance(x,str): return json.dumps(x,ensure_ascii=False)
        if isinstance(x,bool): return str(x).lower()
        if x is None: return '""'
        if isinstance(x,list): return '['+', '.join(val(a) for a in x)+']'
        return str(x)
    scalars={k:x for k,x in v.items() if not isinstance(x,dict)}
    for k,x in scalars.items(): lines.append(f'{k} = {val(x)}')
    for k,x in v.items():
        if isinstance(x,dict):
            if lines: lines.append('')
            lines.append(f'[{k}]')
            for kk,xx in x.items(): lines.append(f'{kk} = {val(xx)}')
    return '\n'.join(lines)

