"""Basic mutation helpers for Dasel-style assignment selectors."""
import json
import re


def _path(text):
    parts = []
    for m in re.finditer(r"(?:^|\.)([A-Za-z_][A-Za-z0-9_-]*)|\[([0-9]+)\]|\[['\"]([^'\"]+)['\"]\]", text.strip()):
        key = next((x for x in m.groups() if x is not None), None)
        if key is None:
            continue
        parts.append(int(key) if m.group(2) is not None else key)
    return parts


def _literal(text, root):
    text = text.strip()
    try:
        return json.loads(text)
    except Exception:
        if text in ("true", "false", "null"):
            return {"true": True, "false": False, "null": None}[text]
        parts = _path(text)
        node = root
        for part in parts:
            node = node[part]
        return node


def assign(data, query):
    """Apply a simple `path = literal` selector, returning (selected, root)."""
    m = re.fullmatch(r"\s*(.*?)\s*=\s*(.*?)\s*", query, re.S)
    if not m:
        raise ValueError("not a simple assignment")
    parts = _path(m.group(1))
    if not parts:
        raise ValueError("empty assignment path")
    value = _literal(m.group(2), data)
    node = data
    for part in parts[:-1]:
        node = node[part]
    node[parts[-1]] = value
    return value, data
"""Helpers for Dasel's --var flag.

The CLI accepts a name=value pair. JSON-like values are decoded as literals;
otherwise the value is interpreted as a selector over the input document.
"""
import json


def parse_var(spec, root, evaluate):
    """Return (name, value) for one --var argument.

    ``evaluate`` is the selector evaluator supplied by the caller and is called
    with (root, selector_text). File values use the documented
    ``name=json:file:path`` form.
    """
    if "=" not in spec:
        raise ValueError("expected name=value")
    name, raw = spec.split("=", 1)
    if not name:
        raise ValueError("variable name cannot be empty")
    if raw.startswith("json:file:"):
        path = raw[len("json:file:"):]
        with open(path, "r", encoding="utf-8") as f:
            return name, json.load(f)
    if raw.startswith("json:"):
        return name, json.loads(raw[len("json:"):])
    try:
        return name, json.loads(raw)
    except (json.JSONDecodeError, TypeError):
        return name, evaluate(root, raw)


def parse_vars(specs, root, evaluate):
    """Parse repeated --var values into a mapping, preserving last value."""
    result = {}
    for spec in specs or []:
        name, value = parse_var(spec, root, evaluate)
        result[name] = value
    return result

