        out={'-'+k:v for k,v in elem.attrib.items()}
        if elem.text and elem.text.strip(): out['#text']=elem.text.strip()
        for child in elem:
            val=convert(child)
            if child.tag in out:
                if not isinstance(out[child.tag],list):out[child.tag]=[out[child.tag]]
                out[child.tag].append(val)
            else:out[child.tag]=val
